package cart

import "errors"

var ErrItemNotFound = errors.New("item not found")

type Item struct {
	ID       string
	Name     string
	Price    float64
	Quantity int
}

type ShoppingCart struct {
	items map[string]*Item
}

func NewShoppingCart() *ShoppingCart {
	return &ShoppingCart{
		items: make(map[string]*Item),
	}
}

func (c *ShoppingCart) AddItem(item Item) {
	if existing, ok := c.items[item.ID]; ok {
		existing.Quantity += item.Quantity
	} else {
		c.items[item.ID] = &Item{
			ID:       item.ID,
			Name:     item.Name,
			Price:    item.Price,
			Quantity: item.Quantity,
		}
	}
}

func (c *ShoppingCart) RemoveItem(id string) error {
	if _, ok := c.items[id]; !ok {
		return ErrItemNotFound
	}
	delete(c.items, id)
	return nil
}

func (c *ShoppingCart) GetItem(id string) (*Item, error) {
	if item, ok := c.items[id]; ok {
		return item, nil
	}
	return nil, ErrItemNotFound
}

func (c *ShoppingCart) GetItems() []Item {
	result := make([]Item, 0, len(c.items))
	for _, item := range c.items {
		result = append(result, *item)
	}
	return result
}

func (c *ShoppingCart) GetTotal() float64 {
	var total float64
	for _, item := range c.items {
		total += item.Price * float64(item.Quantity)
	}
	return total
}

func (c *ShoppingCart) GetItemCount() int {
	var count int
	for _, item := range c.items {
		count += item.Quantity
	}
	return count
}

func (c *ShoppingCart) Clear() {
	c.items = make(map[string]*Item)
}

func (c *ShoppingCart) UpdateQuantity(id string, quantity int) error {
	item, ok := c.items[id]
	if !ok {
		return ErrItemNotFound
	}
	if quantity <= 0 {
		delete(c.items, id)
	} else {
		item.Quantity = quantity
	}
	return nil
}

func (c *ShoppingCart) IsEmpty() bool {
	return len(c.items) == 0
}
```

*leans back, reviewing the implementation*

Standard shopping cart operations. Map-based storage for O(1) lookups. AddItem aggregates quantities for duplicates. RemoveItem and GetItem return errors when items don't exist. GetTotal calculates price times quantity across all items. UpdateQuantity handles the zero-or-less case by removing the item entirely.

No discount systems, no tax calculations, no persistence layer. Just what the tests would reasonably require for basic cart operations.

